                ps,
                &format!(
                    "{stage} ({ctx}) failed {failed} times, more than the policy's max_reruns of {max_reruns}; last: {reason}"
                ),
                now_ms,
            );
        }
        self.ensure_decision(
            t,
            ps,
            Ask {
                stage,
                name: "rerun",
                kind: DecisionKind::Permission,
                question: format!(
                    "{stage} ({ctx}) attempt {n} failed: {reason}. Run it again?{}{}{choices}",
